#include "KS/SRC/ks/FEMenu_shared.h"

class PanelQuad {
    char data[0x194];
public:
    virtual ~PanelQuad();
    virtual void Init(float, float, float, float, float, float, float, float, float, float, float, float, float, char *);
    virtual void TurnOn(bool);
    virtual void SetLayer(int);
    virtual void Rotate(float);
    virtual void Rotate(float, float, float);
    virtual void Update(time_value_t time_inc);
};

class FEEntityManager {
    char data0[0x1c0];
    int cam_stopped;
    int cam_stopped_at;
    char data1[0x204 - 0x1c8];
    int closet_state;
public:
    bool OKtoDrawBoardSelect() { return cam_stopped && cam_stopped_at == 4 && closet_state == 0; }
};

class FEManager {
public:
    char data[12];
    FEEntityManager *em;
};

class BoardFrontEnd : public FEMultiMenu {
    bool unlocked;
    void *sys;
    char data[0x250 - 0x148];
    PanelQuad *red_gauges[4];
    char data2[0x274 - 0x260];
    bool wait_for_camera;
public:
    void Update(time_value_t time_inc);
};

void BoardFrontEnd::Update(time_value_t time_inc)
{
    if(wait_for_camera && manager->em->OKtoDrawBoardSelect()) wait_for_camera = false;
    else if(!wait_for_camera && !manager->em->OKtoDrawBoardSelect()) wait_for_camera = true;

    for(int i=0; i<4; i++)
        red_gauges[i]->Update(time_inc);
    FEMultiMenu::Update(time_inc);
}
